import httpStatus3 from "http-status";
var globalErrorHandler = (err, req, res, next) => {
  let statusCode = err.statusCode || httpStatus3.INTERNAL_SERVER_ERROR;
  let errorMessage = err.message || "Internal Server Error";
  let errName = err.name || "Error";
  if (err instanceof AppError) {
    statusCode = err.statusCode;
    errorMessage = err.message;
  } else if (err instanceof prismaNamespace_exports.PrismaClientValidationError) {
    statusCode = httpStatus3.BAD_REQUEST;
    errorMessage = "You have provided an incorrect or missing field.";
  } else if (err instanceof prismaNamespace_exports.PrismaClientKnownRequestError) {
    if (err.code === "P2002") {
      statusCode = httpStatus3.CONFLICT;
      errorMessage = "A record with this unique value already exists.";
    } else if (err.code === "P2003") {
      statusCode = httpStatus3.BAD_REQUEST;
      errorMessage = "Foreign key constraint failed.";
    } else if (err.code === "P2025") {
      statusCode = httpStatus3.NOT_FOUND;
      errorMessage = "Requested record not found.";
    }
  } else if (err instanceof prismaNamespace_exports.PrismaClientInitializationError) {
    if (err.errorCode === "P1000") {
      statusCode = httpStatus3.UNAUTHORIZED;
      errorMessage = "Database authentication failed.";
    } else if (err.errorCode === "P1001") {
      statusCode = httpStatus3.SERVICE_UNAVAILABLE;
      errorMessage = "Database server is not reachable.";
    }
  } else if (err instanceof prismaNamespace_exports.PrismaClientUnknownRequestError) {
    statusCode = httpStatus3.INTERNAL_SERVER_ERROR;
    errorMessage = "An unknown database error occurred.";
  }
  res.status(statusCode).json({
    success: false,
    statusCode,
    name: errName,
    message: errorMessage,
    error: config_default.mode === "development" ? err.stack : void 0
  });
};

