var createPropertyIntoDB = async (payload, landLordId) => {
  const { pName, pLocation, pPrice, pDescription, pImage, type, description } = payload;
  const normalizedType = type?.trim().toUpperCase();
  const pType = Object.values(PType);
  if (!pType.includes(normalizedType)) {
    throw new AppError(
      "Invalid property type provided. Type must be APARTMENT or apartment, HOUSE or house, STUDIO or studio, OFFICE or office, SHOP or shop, WAREHOUSE or warehouse, LAND or land, OTHER or other and if you are not sure just leave blank.",
      httpStatus4.BAD_REQUEST
    );
  }
  const result = await prisma.property.create({
    data: {
      landLordId,
      pName,
      pLocation,
      pPrice,
      pDescription,
      pImage: pImage ? pImage : "Image not provided",
      category: {
        create: {
          type: normalizedType,
          description: description ? description : "Description not provided"
        }
      }
    },
    select: {
      id: true,
      landLordId: true,
      pName: true,
      pLocation: true,
      pPrice: true,
      pDescription: true,
      pImage: true,
      category: {
        select: {
          id: true,
          type: true,
          description: true
        }
      }
    }
  });
  return result;
};
var updatePropertyInDB = async (req, id, payload) => {
  const landLordId = await prisma.property.findUniqueOrThrow({
    where: {
      id
    },
    select: {
      landLordId: true
    }
  });
  if (landLordId.landLordId != req.user?.userId) {
    throw new AppError(
      "You are not the owner of this property.So, you are not authorized to update this property.",
      httpStatus4.FORBIDDEN
    );
  }
  const { pName, pLocation, pPrice, pDescription, pImage, type, description } = payload;
  const currentProperty = await prisma.property.findUniqueOrThrow({
    where: {
      id
    },
    include: {
      category: true
    }
  });
  const result = await prisma.property.update({
    where: {
      id
    },
    data: {
      pName: pName ? pName : currentProperty.pName,
      pLocation: pLocation ? pLocation : currentProperty.pLocation,
      pPrice: pPrice ? pPrice : currentProperty.pPrice,
      pDescription: pDescription ? pDescription : currentProperty.pDescription,
      pImage: pImage ? pImage : currentProperty.pImage,
      category: {
        update: {
          type: type ? type : currentProperty.category?.type,
          description: description ? description : currentProperty.category?.description
        }
      }
    },
    select: {
      id: true,
      landLordId: true,
      pName: true,
      pLocation: true,
      pPrice: true,
      pDescription: true,
      pImage: true,
      category: {
        select: {
          id: true,
          type: true,
          description: true
        }
      }
    }
  });
  return result;
};
var deletePropertyFromDB = async (userId, id) => {
  const result = await prisma.property.findUniqueOrThrow({
    where: {
      id
    },
    select: {
      landLordId: true
    }
  });
  if (result.landLordId !== userId) {
    throw new AppError(
      "You are not the owner of this property. So, you are not authorized to delete this property.",
      httpStatus4.FORBIDDEN
    );
  }
  await prisma.property.delete({
    where: {
      id
    }
  });
};
var rentalRequestsForLandLordsPropertiesFromDB = async (landLordId) => {
  const properties = await prisma.property.findMany({
    where: {
      landLordId
    },
    select: {
      rentalRequest: {
        select: {
          id: true,
          propertyId: true,
          tenantId: true,
          message: true,
          status: true,
          createdAt: true,
          updatedAt: true
        }
      }
    }
  });
  const rentalRequests = properties.flatMap(
    (property) => property.rentalRequest
  );
  return rentalRequests;
};
var approveOrRejectRentalRequestInDB = async (userId, rentalRequestId, payload) => {
  const rentalRequest = await prisma.rentalRequest.findUniqueOrThrow({
    where: {
      id: rentalRequestId
    },
    select: {
      property: {
        select: {
          landLordId: true
        }
      }
    }
  });
  if (rentalRequest.property.landLordId !== userId) {
    throw new AppError("You are not authorized to approve or reject this rental request as you are not the owner of this property", httpStatus4.FORBIDDEN);
  }
  const result = await prisma.rentalRequest.update({
    where: {
      id: rentalRequestId
    },
    data: {
      status: payload
    }
  });
  return result;
};
