var getAllPropertiesFromDB = async (filterQuery) => {
  const { location, price, type } = filterQuery;
  let andConditions = [];
  if (location) {
    andConditions.push({
      pLocation: {
        contains: location,
        mode: "insensitive"
      }
    });
  }
  if (price) {
    andConditions.push({
      pPrice: {
        equals: Number(price)
      }
    });
  }
  if (type) {
    andConditions.push({
      category: {
        type: type.trim().toUpperCase()
      }
    });
  }
  const result = await prisma.property.findMany({
    where: {
      AND: andConditions
    },
    select: {
      id: true,
      pName: true,
      pLocation: true,
      pPrice: true,
      category: {
        select: {
          id: true,
          type: true
        }
      },
      createdAt: true
    }
  });
  if (result.length === 0) {
    throw new AppError("No properties found with the given filter", httpStatus6.NOT_FOUND);
  }
  return result;
};
